package com.example.domain.model.i18n

internal object DuaIt1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("Al risveglio", "Sia lode ad Allah, che ci ha dato la vita dopo averci fatto morire (dormire), e a Lui è il ritorno.", "Al risveglio dal sonno, per ringraziare Allah.", "Il Profeta ﷺ recitava questa dua al risveglio — iniziando la giornata con gratitudine e ricordo dell'Aldilà."),
        "dua_leaving_home" to DuaText("Uscendo di casa", "Nel nome di Allah; ripongo la mia fiducia in Allah. Non c'è forza né potenza se non in Allah.", "Quando si esce di casa, per la protezione di Allah.", "Gli angeli dicono: 'Sei guidato, provveduto e protetto', e Shaytan si allontana."),
        "dua_anxiety_distress" to DuaText("Sollievo da ansia e tristezza", "O Allah, mi rifugio in Te dall'ansia e dalla tristezza, dall'impotenza e dalla pigrizia, dall'avarizia e dalla codardia, dal peso del debito e dall'essere sopraffatto dagli uomini.", "Nei momenti di tristezza, ansia, debiti e angoscia mentale.", "Il Profeta ﷺ recitava spesso questa dua — rifugio dalla tristezza, dalla pigrizia e dall'ansia del debito."),
        "dua_sayyidul_istighfar" to DuaText("Sayyid al-Istighfar (la migliore richiesta di perdono)", "O Allah, Tu sei il mio Signore; non c'è divinità all'infuori di Te. Mi hai creato e sono Tuo servo; mi attengo al Tuo patto e alla Tua promessa per quanto posso. Mi rifugio in Te dal male che ho commesso. Riconosco il Tuo favore su di me e riconosco il mio peccato; perdonami, poiché nessuno perdona i peccati se non Tu.", "Mattina e sera — la migliore dua di pentimento insegnata dal Profeta ﷺ.", "Chi la recita la sera con certezza e muore quella notte entrerà in Paradiso; lo stesso vale se recitata al mattino."),
        "dua_parents" to DuaText("Dua per i genitori", "Mio Signore, abbi misericordia di loro come essi mi hanno cresciuto quando ero piccolo.", "Una dua coranica per i propri genitori, in cambio delle loro cure nell'infanzia.", "Allah stesso ci ha comandato questa dua per i genitori."),
        "dua_entering_mosque" to DuaText("Entrando in moschea", "O Allah, aprimi le porte della Tua misericordia.", "Entrando in moschea con il piede destro.", "Il Profeta ﷺ insegnò questa dua per entrare in moschea."),
        "dua_morning_asbahna" to DuaText("Il ricordo del mattino", "Siamo giunti al mattino, e con noi tutto il dominio è giunto al mattino appartenendo ad Allah. Ogni lode appartiene ad Allah. Non c'è divinità all'infuori di Allah, Unico, senza soci. A Lui appartiene il dominio e a Lui la lode, ed Egli ha potere su ogni cosa.", "Una dua sunnah recitata al mattino.", "La giornata inizia affermando la sovranità e l'unicità di Allah."),
        "dua_evening_amsayna" to DuaText("Il ricordo della sera", "Siamo giunti alla sera, e con noi tutto il dominio è giunto alla sera appartenendo ad Allah. Ogni lode appartiene ad Allah. Non c'è divinità all'infuori di Allah, Unico, senza soci. A Lui appartiene il dominio e a Lui la lode, ed Egli ha potere su ogni cosa.", "Una dua sunnah recitata alla sera.", "La notte inizia affermando la sovranità e l'unicità di Allah."),
        "dua_bismillah_la_yadurru" to DuaText("Protezione da ogni male", "Nel nome di Allah, con il cui nome nulla può nuocere sulla terra o nei cieli, ed Egli è l'Audiente, il Sapiente.", "Tre volte ogni mattina e sera.", "Chi la dice tre volte al mattino e alla sera, nulla gli nuocerà."),
        "dua_raditu_billahi" to DuaText("Soddisfazione in Allah come Signore", "Sono soddisfatto di Allah come mio Signore, dell'Islam come mia religione e di Muhammad ﷺ come mio Profeta.", "Tre volte al mattino e alla sera.", "Diventa un diritto su Allah compiacerlo nel Giorno del Giudizio."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah mi basta)", "Allah mi basta; non c'è divinità all'infuori di Lui. In Lui ripongo la mia fiducia, ed Egli è il Signore del Trono Maestoso.", "Sette volte al mattino e alla sera.", "Un versetto del Corano; Allah basta contro le preoccupazioni di questo mondo e dell'Aldilà."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("Gloria e lode ad Allah", "Gloria ad Allah e Sua è ogni lode.", "Cento volte al giorno.", "Chi la dice cento volte al giorno ottiene il perdono dei peccati, anche se fossero come la schiuma del mare."),
        "dua_tahleel_100" to DuaText("Non c'è divinità all'infuori di Allah (cento volte)", "Non c'è divinità all'infuori di Allah, Unico, senza soci. A Lui appartiene il dominio e a Lui la lode, ed Egli ha potere su ogni cosa.", "Grande merito nel dirla cento volte al giorno.", "La ricompensa di liberare dieci schiavi, cento buone azioni scritte, cento peccati cancellati e protezione da Shaytan fino alla sera."),
        "dua_leaving_mosque" to DuaText("Uscendo dalla moschea", "O Allah, Ti chiedo della Tua grazia.", "Uscendo dalla moschea con il piede sinistro.", "Si chiede la grazia e il sostentamento di Allah quando si lascia la moschea."),
        "dua_after_adhan" to DuaText("Dopo l'adhan", "O Allah, Signore di questo appello perfetto e della preghiera che sta per essere istituita, concedi a Muhammad ﷺ al-Wasilah e il pregio, ed elevalo alla Stazione Lodata che gli hai promesso.", "Dopo il termine dell'adhan.", "Chi lo dice otterrà l'intercessione del Profeta ﷺ nel Giorno del Giudizio."),
        "dua_after_salah_istighfar" to DuaText("Dopo la preghiera obbligatoria", "Chiedo perdono ad Allah (3 volte). O Allah, Tu sei as-Salam e da Te viene la pace. Benedetto sei Tu, o Possessore di Maestà e Onore.", "Subito dopo il saluto finale.", "Il Profeta ﷺ recitava questo dopo ogni preghiera obbligatoria."),
        "dua_after_salah_help_dhikr" to DuaText("Aiutami a ricordarti", "O Allah, aiutami a ricordarTi, a ringraziarTi e ad adorarTi nel modo migliore.", "Dopo ogni preghiera — il Profeta ﷺ lo consigliò a Mu'adh (che Allah sia soddisfatto di lui).", "Un consiglio speciale del Profeta ﷺ — eccellenza e costanza nell'adorazione."),
        "dua_ayatul_kursi" to DuaText("Ayat al-Kursi dopo la preghiera", "Allah — non c'è divinità all'infuori di Lui, il Vivente, il Sostenitore di ogni cosa. Non Lo coglie né sonnolenza né sonno. A Lui appartiene tutto ciò che è nei cieli e sulla terra. Chi può intercedere presso di Lui senza il Suo permesso? Egli conosce ciò che è davanti e dietro le creature. Esse non abbracciano nulla della Sua scienza, se non ciò che Egli vuole. Il Suo Trono abbraccia i cieli e la terra, e custodirli non Lo affatica. Egli è l'Altissimo, il Grandioso.", "Dopo ogni preghiera obbligatoria e prima di dormire.", "Solo la morte separa dal Paradiso chi la recita dopo ogni preghiera obbligatoria; recitata prima di dormire, protegge fino al mattino."),
        "dua_before_sleep" to DuaText("Prima di dormire", "O Allah, nel Tuo nome muoio (dormo) e vivo (mi risveglio).", "Dopo essersi coricati.", "Il Profeta ﷺ la recitava prima di dormire."),
        "dua_sleep_tasbeeh" to DuaText("Il tasbih di Fatimah prima di dormire", "Gloria ad Allah (33 volte), ogni lode appartiene ad Allah (33 volte), Allah è il Più Grande (34 volte).", "Prima di dormire — il Profeta ﷺ lo insegnò a Fatimah e Ali (che Allah sia soddisfatto di loro).", "Il Profeta ﷺ disse che è meglio per voi di un servo."),
        "dua_sleep_qina_adhab" to DuaText("Protezione dal castigo", "O Allah, proteggimi dal Tuo castigo nel Giorno in cui risusciterai i Tuoi servi.", "Tre volte, con la mano destra sotto la guancia.", "Trasforma il sonno in un ricordo della morte e in preparazione per l'Aldilà."),
        "dua_bad_dream" to DuaText("Dopo un brutto sogno", "Mi rifugio in Allah da Shaytan, il maledetto.", "Dopo un brutto sogno: sputare leggermente a sinistra tre volte, poi girarsi sull'altro fianco.", "Il brutto sogno non ti nuocerà; non raccontarlo a nessuno."),
        "dua_yunus" to DuaText("La dua del Profeta Yunus (as)", "Non c'è divinità all'infuori di Te; gloria a Te. In verità sono stato tra gli ingiusti.", "La dua del Profeta Yunus (as) nel ventre della balena — per ogni difficoltà.", "Qualunque musulmano faccia questa dua per qualsiasi questione, Allah gli risponde."),
        "dua_karb" to DuaText("Nei momenti di grave difficoltà", "Non c'è divinità all'infuori di Allah, il Maestoso, il Clemente. Non c'è divinità all'infuori di Allah, Signore del Trono Maestoso. Non c'è divinità all'infuori di Allah, Signore dei cieli, Signore della terra e Signore del Nobile Trono.", "Nei momenti di grave difficoltà e angustia.", "Il Profeta ﷺ la recitava nei momenti di difficoltà."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("O Vivente, o Sostenitore", "O Vivente, o Sostenitore di ogni cosa! Per la Tua misericordia chiedo aiuto.", "Quando una questione diventa molto pesante.", "Ogni volta che qualcosa angustiava il Profeta ﷺ, egli diceva questo."),
        "dua_hasbunallah" to DuaText("Allah ci basta e Ottimo è il Disponente", "Allah ci basta ed Egli è il migliore Disponente delle cose.", "Quando si teme un nemico o si affronta un grande pericolo.", "Il Profeta Ibrahim (as) lo disse quando fu gettato nel fuoco, e il Profeta ﷺ lo disse nei momenti di pericolo."),
        "dua_entering_home" to DuaText("Entrando in casa", "Nel nome di Allah.", "Menzionare il nome di Allah e salutare con il salam entrando in casa.", "Quando Allah viene ricordato entrando in casa e durante i pasti, Shaytan dice: non c'è posto per voi qui né cena."),
        "dua_travel" to DuaText("Dua per il viaggio (in veicolo)", "Gloria a Colui che ci ha sottomesso questo, e non avremmo potuto farlo da soli; e certamente al nostro Signore ritorneremo.", "Dopo essersi seduti sul veicolo e aver detto Allahu Akbar tre volte.", "La dua sunnah del viaggio, per protezione e benedizione."),
        "dua_entering_market" to DuaText("Entrando al mercato", "Non c'è divinità all'infuori di Allah, Unico, senza soci. A Lui appartiene il dominio e a Lui la lode. Egli dà la vita e dà la morte, ed è Vivente e mai muore. Nella Sua mano è ogni bene, ed Egli ha potere su ogni cosa.", "Entrando al mercato.", "Il hadith menziona una grande ricompensa (un milione di buone azioni)."),
        "dua_adam_forgiveness" to DuaText("La dua del Profeta Adamo (as)", "Nostro Signore, abbiamo fatto torto a noi stessi, e se non ci perdoni e non abbia misericordia di noi, saremo certamente tra i perdenti.", "La dua di pentimento di Adamo ed Hawwa (as).", "Il primo pentimento dell'umanità — Allah lo accettò."),
        "dua_abu_bakr" to DuaText("Insegnata ad Abu Bakr (ra)", "O Allah, ho fatto grande torto a me stesso, e nessuno perdona i peccati se non Tu; concedimi perdono da parte Tua e abbi misericordia di me. In verità Tu sei il Perdonatore, il Misericordioso.", "Il Profeta ﷺ la insegnò ad Abu Bakr as-Siddiq (ra) da dire nella preghiera (dopo il tashahhud).", "Una dua sunnah per la fine della preghiera."),
        "dua_astaghfirullah_atubu" to DuaText("Istighfar quotidiano", "Chiedo perdono ad Allah e a Lui mi rivolgo pentito.", "Il Profeta ﷺ chiedeva perdono più di settanta volte al giorno.", "Il Profeta ﷺ disse: chiedo perdono ad Allah e mi pento a Lui più di settanta volte al giorno."),
        "dua_laylatul_qadr" to DuaText("Dua per Laylat al-Qadr", "O Allah, Tu sei Colui che molto perdona e ami perdonare, perdonami dunque.", "Insegnata ad Aisha (ra) per Laylat al-Qadr.", "Una dua speciale per le ultime notti del Ramadan e Laylat al-Qadr."),
        "dua_family_coolness" to DuaText("La frescura degli occhi (coniuge e figli)", "Nostro Signore, concedici dai nostri coniugi e dalla nostra progenie la frescura dei nostri occhi, e fa' di noi guide per i timorati.", "Una dua coranica per un coniuge e dei figli virtuosi.", "Per la pace in famiglia e figli virtuosi."),
        "dua_righteous_children" to DuaText("Per una progenie virtuosa", "Mio Signore, concedimi da parte Tua una progenie pura. In verità Tu sei Colui che ascolta la supplica.", "La dua del Profeta Zakariyya (as).", "Una dua coranica per chi desidera dei figli."),
        "dua_ibrahim_prayer_family" to DuaText("Coloro che eseguono la preghiera", "Mio Signore, fa' di me e della mia discendenza coloro che eseguono la preghiera. Nostro Signore, accetta la mia supplica. Nostro Signore, perdona me, i miei genitori e i credenti nel Giorno in cui sarà reso il conto.", "La dua del Profeta Ibrahim (as) per sé e per la sua discendenza.", "Comunemente recitata alla fine della preghiera."),
        "dua_newlywed" to DuaText("Congratulazioni ai novelli sposi", "Che Allah ti benedica, ti conceda benedizioni e vi unisca entrambi nel bene.", "Nel congratularsi per un matrimonio.", "La congratulazione sunnah per un matrimonio."),
        "dua_before_eating" to DuaText("Prima di mangiare", "Nel nome di Allah. (Se dimenticato:) Nel nome di Allah, all'inizio e alla fine.", "Prima di mangiare; se dimenticato, dirlo a metà pasto.", "Dire Bismillah impedisce a Shaytan di condividere il cibo."),
        "dua_after_eating" to DuaText("Dopo aver mangiato", "Ogni lode appartiene ad Allah che mi ha nutrito con questo e me lo ha provveduto senza alcuna forza né potenza da parte mia.", "Dopo aver finito il pasto.", "I peccati passati di chi la dice vengono perdonati."),
        "dua_host" to DuaText("Per l'ospitante", "O Allah, benedici ciò che hai loro provveduto, perdonali e abbi misericordia di loro.", "Per l'ospitante, dopo aver mangiato a casa di qualcuno.", "Ringraziare l'ospitante nel modo sunnah."),
        "dua_breaking_fast" to DuaText("Nel rompere il digiuno", "La sete è andata, le vene si sono inumidite, e la ricompensa è confermata, se Allah vuole.", "Al momento dell'iftar.", "Il Profeta ﷺ diceva questo rompendo il digiuno."),
        "dua_new_clothes" to DuaText("Indossando abiti nuovi", "O Allah, ogni lode è Tua; mi hai vestito con questo. Ti chiedo il suo bene e il bene per cui è stato fatto, e mi rifugio in Te dal suo male e dal male per cui è stato fatto.", "Indossando un capo nuovo (nominandolo, come una camicia o un turbante).", "Il Profeta ﷺ faceva questa dua indossando abiti nuovi. (La dua quotidiana per vestirsi è sotto 'Vestirsi'.)"),
        "dua_rabbana_atina" to DuaText("Il bene in questo mondo e nell'Aldilà", "Nostro Signore, dacci il bene in questo mondo e il bene nell'Aldilà, e proteggici dal castigo del Fuoco.", "La dua che il Profeta ﷺ faceva più spesso.", "Una dua che riunisce ogni bene di questo mondo e dell'Aldilà."),
        "dua_rabbi_zidni_ilma" to DuaText("Aumento della conoscenza", "Mio Signore, accresci la mia conoscenza.", "Per un aumento di conoscenza.", "Allah comandò al Profeta ﷺ di chiedere solo un aumento della conoscenza."),
        "dua_musa_sharh_sadr" to DuaText("L'apertura del petto (Musa as)", "Mio Signore, allargami il petto, facilita il mio compito e sciogli il nodo dalla mia lingua, affinché comprendano il mio parlare.", "Prima di un esame, un discorso o un compito difficile.", "La dua del Profeta Musa (as) — calma del cuore e facilità nel proprio lavoro."),
        "dua_la_tuzigh" to DuaText("La fermezza del cuore", "Nostro Signore, non far deviare i nostri cuori dopo averci guidato, e concedici misericordia da parte Tua. In verità Tu sei il Munifico.", "Per la fermezza sulla retta via.", "Una dua per rimanere saldi nella fede."),
        "dua_ya_muqallib" to DuaText("O Colui che volge i cuori", "O Colui che volge i cuori, rendi saldo il mio cuore sulla Tua religione.", "Il Profeta ﷺ faceva spesso questa dua.", "Secondo Umm Salamah (ra), la dua che il Profeta ﷺ faceva più spesso."),
        "dua_la_tuakhidhna" to DuaText("Gli ultimi versetti della Sura al-Baqarah", "Nostro Signore, non punirci se dimentichiamo o sbagliamo. Nostro Signore, non imporci un peso come quello che imponesti a coloro prima di noi. Nostro Signore, non caricarci di ciò che non possiamo sopportare. Perdonaci, assolvici e abbi misericordia di noi. Tu sei il nostro Protettore, aiutaci contro il popolo miscredente.", "Di notte prima di dormire — gli ultimi due versetti della Sura al-Baqarah.", "Chi recita gli ultimi due versetti della Sura al-Baqarah di notte, questi gli basteranno."),
        "dua_visiting_sick" to DuaText("Visitando un malato", "Chiedo ad Allah, il Maestoso, Signore del Trono Maestoso, di guarirti.", "Sette volte visitando un malato.", "Se il momento della morte non è giunto, Allah lo guarirà."),
        "dua_ruqyah_pain" to DuaText("Per il dolore fisico", "Mi rifugio in Allah e nel Suo potere dal male di ciò che sento e temo.", "Porre la mano dove fa male, dire Bismillah tre volte, poi questa dua sette volte.", "Il Profeta ﷺ la insegnò a Uthman ibn Abil-'As (ra) per il dolore."),
        "dua_ruqyah_nabawi" to DuaText("La ruqyah profetica per il malato", "O Allah, Signore dell'umanità! Rimuovi il male e concedi la guarigione, poiché Tu sei Colui che guarisce; non c'è guarigione se non la Tua guarigione — una guarigione che non lascia alcuna malattia.", "Passando la mano sul malato.", "Il Profeta ﷺ la recitava visitando i malati della sua famiglia."),
        "dua_kalimat_tammat" to DuaText("Rifugio nelle parole perfette di Allah", "Mi rifugio nelle parole perfette di Allah dal male di ciò che Egli ha creato.", "Fermandosi in un luogo, o alla sera.", "Chi si ferma in un luogo e dice questo, nulla gli nuocerà finché non se ne va."),
        "dua_evil_eye" to DuaText("Protezione per i bambini (malocchio)", "Cerco protezione per voi due nelle parole perfette di Allah da ogni demonio e da ogni creatura velenosa, e da ogni occhio dannoso.", "Il Profeta ﷺ la recitava su Hasan e Husain (ra).", "Una dua sunnah per proteggere i bambini dal malocchio e dal male (per un solo bambino dire 'U'idhuka')."),
        "dua_seeing_afflicted" to DuaText("Vedendo qualcuno afflitto", "Ogni lode appartiene ad Allah che mi ha risparmiato da ciò con cui ha provato te, e mi ha favorito rispetto a molte delle Sue creature.", "Vedendo qualcuno in prova (dirlo sottovoce tra sé).", "Chi lo dice è protetto da quella prova."),
        "dua_istikhara" to DuaText("La preghiera di Istikhara", "O Allah, cerco il bene tramite la Tua conoscenza, cerco la capacità tramite il Tuo potere, e Ti chiedo della Tua grande grazia. Tu hai potere e io non ne ho; Tu sai e io non so, e Tu sei il Conoscitore dell'invisibile. O Allah, se nella Tua conoscenza questa cosa (pensarla) è un bene per la mia religione, la mia vita e il mio destino, allora decretala per me, rendimela facile e benedicimela. E se nella Tua conoscenza questa cosa è un male per la mia religione, la mia vita e il mio destino, allora allontanala da me e allontanami da essa, e decreta per me il bene ovunque esso sia, e poi rendimi soddisfatto di esso.", "Dopo due rak'ah di preghiera volontaria, per cercare il meglio in una questione lecita.", "Il Profeta ﷺ insegnò l'istikhara ai Compagni come insegnava loro una sura del Corano."),
        "dua_allahumma_bika_asbahna" to DuaText("O Allah, per Te entriamo nel mattino", "O Allah, per Te entriamo nel mattino e per Te entriamo nella sera; per Te viviamo e per Te moriamo, e a Te è la resurrezione.", "Al mattino.", "Il Profeta ﷺ insegnò ai Compagni a dire questo mattina e sera."),
        "dua_allahumma_bika_amsayna" to DuaText("O Allah, per Te entriamo nella sera", "O Allah, per Te entriamo nella sera e per Te entriamo nel mattino; per Te viviamo e per Te moriamo, e a Te è il ritorno.", "Alla sera.", "Il Profeta ﷺ insegnò ai Compagni a dire questo mattina e sera."),
        "dua_afiyah_morning" to DuaText("Chiedendo il benessere", "O Allah, Ti chiedo perdono e benessere in questo mondo e nell'Aldilà.", "Il Profeta ﷺ non tralasciò mai questa dua, mattina o sera.", "A nessuno è stato dato nulla di meglio del benessere."),
        "dua_afini_fi_badani" to DuaText("Salute del corpo, dell'udito e della vista", "O Allah, concedi salute al mio corpo. O Allah, concedi salute al mio udito. O Allah, concedi salute alla mia vista. Non c'è divinità all'infuori di Te.", "Tre volte ogni mattina e sera.", "Una dua per la salute e la protezione dei sensi."),
        "dua_ya_hayyu_aslih" to DuaText("Sistema tutti i miei affari", "O Vivente, o Sostenitore, per la Tua misericordia chiedo aiuto: sistema tutti i miei affari e non lasciarmi a me stesso nemmeno per un batter d'occhio.", "Il Profeta ﷺ consigliò a Fatimah (ra) di dirlo mattina e sera.", "Chiedere l'aiuto di Allah in ogni questione."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Il tasbih di Juwayriyah (ra)", "Gloria ad Allah e Sua è ogni lode — quanto le Sue creature, quanto Gli piace, quanto il peso del Suo Trono e l'inchiostro delle Sue parole.", "Tre volte al mattino — più pesante di ore di dhikr.", "Dire queste quattro frasi tre volte supera il dhikr dall'alba fino a metà mattina."),
        "dua_salawat" to DuaText("Durood Ibrahimi", "O Allah, benedici Muhammad ﷺ e la famiglia di Muhammad come benedicesti Ibrahim (as) e la famiglia di Ibrahim; Tu sei Degno di lode, Glorioso. O Allah, favorisci Muhammad ﷺ e la famiglia di Muhammad come favoristi Ibrahim (as) e la famiglia di Ibrahim; Tu sei Degno di lode, Glorioso.", "Salawat sul Profeta ﷺ nella preghiera e in ogni momento.", "Chi invia salawat una volta, Allah invia dieci misericordie su di lui (Muslim 408)."),
        "dua_wudu_after" to DuaText("Dopo l'abluzione", "Attesto che non c'è divinità all'infuori di Allah, Unico, senza soci, e che Muhammad ﷺ è Suo servo e Messaggero. O Allah, fammi tra coloro che si pentono e coloro che si purificano.", "Dopo aver completato il wudu.", "Le otto porte del Paradiso gli vengono aperte, da entrare per quella che vuole."),
        "dua_wudu_before" to DuaText("Prima dell'abluzione", "Nel nome di Allah.", "Iniziando il wudu.", "Non c'è (completa) abluzione per chi non menziona il nome di Allah su di essa."),
        "dua_istiftah" to DuaText("Supplica di apertura della preghiera", "Gloria a Te, o Allah, e lode a Te. Benedetto è il Tuo nome, esaltata è la Tua maestà, e non c'è divinità all'infuori di Te.", "All'inizio della preghiera, subito dopo il takbir di apertura.", "La dua sunnah di apertura della preghiera."),
        "dua_ruku" to DuaText("Nel ruku", "Gloria al mio Signore, il Magnifico.", "Almeno tre volte nel ruku.", "Il tasbih sunnah del ruku."),
        "dua_sujood" to DuaText("Nel sujood", "Gloria al mio Signore, l'Altissimo.", "Almeno tre volte nel sujood.", "Il servo è più vicino al suo Signore durante la prostrazione (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Alzandosi dal ruku", "Allah ascolta chi Lo loda. Nostro Signore, a Te appartiene ogni lode.", "Alzandosi dal ruku e stando eretti.", "A chi il suo 'Rabbana wa lakal-hamd' coincide con quello degli angeli, vengono perdonati i peccati passati."),
        "dua_between_sajdas" to DuaText("Tra le due prostrazioni", "Mio Signore, perdonami. Mio Signore, perdonami.", "Seduti tra le due prostrazioni.", "La dua sunnah della seduta tra le prostrazioni."),
        "dua_before_salam_four" to DuaText("Rifugio da quattro cose prima del saluto", "O Allah, mi rifugio in Te dal castigo dell'Inferno, dal castigo della tomba, dalle prove della vita e della morte, e dal male della prova del falso Messia (Dajjal).", "Dopo l'ultimo tashahhud e salawat, prima del saluto finale.", "Il Profeta ﷺ comandò di cercare rifugio da queste quattro cose."),
        "dua_qunoot_witr" to DuaText("Qunoot nella preghiera Witr", "O Allah, guidami tra coloro che hai guidato, concedimi benessere tra coloro cui hai concesso benessere, prenditi cura di me tra coloro di cui Ti sei preso cura, benedicimi in ciò che mi hai dato, e proteggimi dal male di ciò che hai decretato. Tu decreti e nessuno decreta contro di Te, e chi Ti è amico non è mai umiliato. Benedetto ed Esaltato sei Tu, nostro Signore.", "Nella preghiera witr — il Profeta ﷺ la insegnò a Hasan ibn Ali (ra).", "Il qunoot sunnah del witr. (Tra gli Hanafiti è nota anche 'Allahumma inna nasta'inuka'.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma inna nasta'inuka)", "O Allah, cerchiamo il Tuo aiuto e il Tuo perdono, crediamo in Te e confidiamo in Te, Ti lodiamo nel modo migliore, Ti ringraziamo e non siamo ingrati, e abbandoniamo chi Ti disobbedisce. O Allah, solo Te adoriamo, a Te preghiamo e ci prostriamo, verso di Te ci affrettiamo e ci sforziamo, speriamo nella Tua misericordia e temiamo il Tuo castigo; in verità il Tuo castigo raggiungerà i miscredenti.", "Nel witr — la pratica degli Hanafiti.", "Riportato da Umar (ra) nel qunoot."),
        "dua_sleep_aslamtu" to DuaText("Le ultime parole prima di dormire", "O Allah, mi sottometto a Te, affido a Te la mia questione e affido la mia schiena alla Tua protezione, per speranza in Te e timore di Te. Non c'è rifugio né scampo da Te se non a Te. Credo nel Tuo Libro che hai rivelato e nel Tuo Profeta che hai inviato.", "Dopo il wudu, sdraiandosi sul fianco destro — le ultimissime parole prima di dormire.", "Se muore quella notte, muore sulla fitrah (Islam)."),
        "dua_waking_night" to DuaText("Svegliandosi durante la notte", "Non c'è divinità all'infuori di Allah, Unico, senza soci. A Lui appartiene il dominio e a Lui la lode, ed Egli ha potere su ogni cosa. Ogni lode appartiene ad Allah, gloria ad Allah, non c'è divinità all'infuori di Allah, Allah è il Più Grande, e non c'è forza né potenza se non in Allah. O Allah, perdonami.", "Svegliandosi durante la notte.", "La sua dua viene esaudita, e se fa il wudu e prega, la sua preghiera viene accettata."),
        "dua_hamm_ibn_masud" to DuaText("Dua nell'afflizione (Ibn Mas'ud)", "O Allah, sono Tuo servo, figlio del Tuo servo, figlio della Tua serva. La mia fronte è nella Tua mano, il Tuo comando su di me si compie, e il Tuo decreto su di me è giusto. Ti chiedo per ogni nome che è Tuo, con cui Ti sei nominato, o che hai rivelato nel Tuo Libro, o che hai insegnato a qualcuna delle Tue creature, o che hai tenuto per Te nella scienza dell'invisibile — di rendere il Corano la primavera del mio cuore, la luce del mio petto, la rimozione della mia tristezza e la partenza della mia preoccupazione.", "Nell'afflizione e nella difficoltà — Allah sostituisce la tristezza con la gioia.", "Allah rimuove la sua preoccupazione e tristezza e gli concede gioia al loro posto."),
        "dua_difficulty_sahl" to DuaText("Quando qualcosa è difficile", "O Allah, nulla è facile se non ciò che Tu rendi facile, e Tu rendi facile il difficile se vuoi.", "Quando qualcosa sembra difficile.", "Facilità negli esami e nei compiti difficili."),
        "dua_musibah" to DuaText("In caso di calamità (Istirja)", "Apparteniamo ad Allah e a Lui ritorneremo. O Allah, ricompensami nella mia afflizione e sostituiscila con qualcosa di migliore.", "In caso di qualsiasi perdita o calamità.", "Allah certamente dà qualcosa di migliore — a Umm Salamah (ra) fu dato il Profeta ﷺ."),
        "dua_debt" to DuaText("Per il sollievo dal debito", "O Allah, bastami con ciò che hai reso lecito contro ciò che hai reso illecito, e con la Tua grazia rendimi indipendente da tutti tranne Te.", "Per saldare i debiti — insegnata da Ali (ra).", "Anche se il debito fosse come una montagna, Allah lo salderà."),
        "dua_anger" to DuaText("Quando si è arrabbiati", "Mi rifugio in Allah da Shaytan, il maledetto.", "Quando si è arrabbiati.", "Il Profeta ﷺ disse: se dice questo, la sua rabbia se ne andrà."),
        "dua_waswasa" to DuaText("Contro i dubbi sulla fede", "Credo in Allah e nei Suoi Messaggeri.", "Quando arrivano sussurri satanici sulla fede.", "Quando arriva il sussurro, dire questo e fermarsi lì (e cercare rifugio in Allah)."),
        "dua_travel_full" to DuaText("Supplica completa del viaggio", "O Allah, Ti chiediamo in questo viaggio rettitudine e devozione, e opere che Ti compiacciano. O Allah, rendici facile questo viaggio e accorcia la sua distanza. O Allah, Tu sei il Compagno nel viaggio e il Custode della famiglia.", "Iniziando un viaggio, dopo 'Subhanalladhi sakhkhara'.", "La dua sunnah completa del viaggio."),
        "dua_return_travel" to DuaText("Tornando da un viaggio", "Torniamo, pentiti, adorando e lodando il nostro Signore.", "Tornando da un viaggio.", "Il Profeta ﷺ diceva questo tornando da un viaggio."),
        "dua_farewell_traveller" to DuaText("Salutando un viaggiatore", "Affido ad Allah la tua religione, la tua fiducia e l'esito delle tue azioni.", "Salutando un viaggiatore.", "Ciò che è affidato ad Allah non va mai perduto."),
        "dua_entering_town" to DuaText("Fermandosi in un luogo", "Mi rifugio nelle parole perfette di Allah dal male di tutto ciò che ha creato.", "Fermandosi in un luogo o arrivando in una nuova città.", "Nulla gli nuocerà finché non se ne va."),
        "dua_boarding_ship" to DuaText("Salendo su una nave/veicolo", "Nel nome di Allah è la sua navigazione e il suo ancoraggio. In verità il mio Signore è Perdonatore, Misericordioso.", "Salendo su una nave o veicolo — le parole del Profeta Nuh (as).", "Un versetto coranico — la dua dell'arca di Nuh (as)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar con Hayyul-Qayyum", "Chiedo perdono ad Allah, oltre il Quale non c'è divinità, il Vivente, il Sostenitore, e a Lui mi rivolgo pentito.", "Per il pentimento.", "I suoi peccati sono perdonati anche se fosse fuggito dal campo di battaglia."),
        "dua_rabbighfir_warham" to DuaText("Mio Signore, perdona e abbi misericordia", "Mio Signore, perdona e abbi misericordia, poiché Tu sei il migliore di coloro che mostrano misericordia.", "Una dua coranica — per il perdono e la misericordia.", "L'ultimo versetto della Sura al-Mu'minun."),
        "dua_majlis_kaffarah" to DuaText("Espiazione dell'assemblea", "Gloria a Te, o Allah, e lode a Te. Attesto che non c'è divinità all'infuori di Te. Chiedo il Tuo perdono e mi rivolgo a Te pentito.", "Alzandosi da un'assemblea.", "Diventa un'espiazione per qualsiasi male detto nell'assemblea."),
        "dua_jami_forgiveness" to DuaText("Perdono completo", "O Allah, perdona i miei errori, la mia ignoranza, il mio eccesso nelle mie questioni, e tutto ciò che Tu conosci meglio di me.", "Una dua completa del Profeta ﷺ.", "Il Profeta ﷺ era solito fare questa dua."),
        "dua_parents_nuh" to DuaText("La dua di Nuh (as) per i genitori", "Mio Signore, perdona me, i miei genitori, chiunque entri nella mia casa come credente, e tutti i credenti e le credenti.", "Per i propri genitori e i credenti.", "La dua del Profeta Nuh (as)."),
        "dua_shukr_parents" to DuaText("Gratitudine per i genitori e progenie virtuosa", "Mio Signore, permettimi di essere grato per il Tuo favore che hai concesso a me e ai miei genitori, e di compiere opere virtuose che Ti compiacciano, e rendi virtuosa la mia progenie. A Te mi rivolgo pentito e sono tra coloro che si sottomettono.", "La dua coranica del raggiungimento dei quarant'anni.", "Gratitudine, buone azioni e la rettitudine dei propri figli — tutto in una dua."),
        "dua_intimacy" to DuaText("Prima dell'intimità coniugale", "Nel nome di Allah. O Allah, tieni Shaytan lontano da noi e tieni Shaytan lontano da ciò che (figli) ci concedi.", "Prima dei rapporti coniugali.", "Se un figlio è decretato, Shaytan non gli nuocerà mai."),
        "dua_ibrahim_children_protection" to DuaText("Protezione della casa e dei figli", "Mio Signore, rendi sicura questa città e tieni me e i miei figli lontani dall'adorare gli idoli.", "La dua del Profeta Ibrahim (as) — per la sicurezza della città e dei suoi figli.", "Una dua per rimanere saldi nel tawhid."),
        "dua_drinking_milk" to DuaText("Bevendo latte", "O Allah, benedicicelo e dacene di più.", "Bevendo latte.", "Il latte basta sia come cibo che come bevanda."),
        "dua_iftar_host" to DuaText("Rompendo il digiuno a casa di qualcuno", "Che i digiunanti rompano il digiuno da te, che i virtuosi mangino il tuo cibo, e che gli angeli preghino per te.", "Rompendo il digiuno a casa di qualcuno.", "La dua del Profeta ﷺ per l'ospitante."),
        "dua_seeing_first_fruit" to DuaText("Vedendo il primo frutto", "O Allah, benedicici nei nostri frutti, benedicici nella nostra città, e benedicici nel nostro sa' e nel nostro mudd (misure).", "Vedendo il primo frutto della stagione.", "Una dua per la benedizione nel sostentamento e nella propria città."),
        "dua_good_news" to DuaText("Ricevendo buone notizie", "Ogni lode appartiene ad Allah, per il cui favore le cose buone si compiono.", "Ricevendo buone notizie (ed eseguendo la prostrazione di gratitudine).", "Il Profeta ﷺ lo diceva vedendo qualcosa che gli piaceva."),
        "dua_looking_mirror" to DuaText("Guardandosi allo specchio", "O Allah, come hai reso bello il mio aspetto, rendi buono anche il mio carattere.", "Guardandosi allo specchio.", "Il Profeta ﷺ faceva questa dua (è stabilita anche senza menzione dello specchio)."),
        "dua_rabbana_taqabbal" to DuaText("Accettazione delle opere", "Nostro Signore, accetta questo da noi; in verità Tu sei l'Audiente, il Sapiente. E accetta il nostro pentimento; in verità Tu sei Colui che accetta il pentimento, il Misericordioso.", "Chiesta da Ibrahim e Isma'il (as) mentre costruivano la Ka'bah.", "Una dua per l'accettazione dopo ogni buona azione."),
    )
}
